/** Current-reader assertions shared by permanent witness tests; no old classpath or private path is required. */
final class PairedDomainQualificationTestSupport {
	static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	static final String BASE = "urn:paired-domain-old-writer:";
	static final IRI P = VF.createIRI(BASE + "p");
	static final IRI GRAPH = VF.createIRI(BASE + "graph");

	private PairedDomainQualificationTestSupport() {
	}

	static void freezeClosedOutput(Path source, Path copy) throws Exception {
		Files.createDirectory(copy);
		try (var paths = Files.walk(source)) {
			for (Path file : paths.toList()) {
				assertFalse(Files.isSymbolicLink(file),
						"unexpected capture input must be reviewed, not followed or pruned");
				if (!Files.isRegularFile(file) || file.getFileName().toString().equals("lock")
						|| file.getFileName().toString().equals("lock.mdb")) {
					continue;
				}
				Path destination = copy.resolve(source.relativize(file));
				Files.createDirectories(destination.getParent());
				Files.copy(file, destination);
				assertEquals(java.util.HexFormat.of()
						.formatHex(java.security.MessageDigest.getInstance("SHA-256")
								.digest(Files.readAllBytes(file))),
						java.util.HexFormat.of()
								.formatHex(
										java.security.MessageDigest.getInstance("SHA-256")
												.digest(Files.readAllBytes(destination))));
			}
		}
	}

	static PreparedBulkStore.Snapshot assertClosedWitness(Path directory, boolean inline) {
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		PreparedBulkStore.Snapshot snapshot = PreparedBulkStore.read(directory, properties,
				config(inline, false, false));
		assertNotNull(snapshot, "the exact closed current generation is natively clean");
		assertTrue(RdfTermDomainQualification.matches(properties, snapshot),
				"the witness records BOTH final native transactions and generation, rather than startup identities");
		return snapshot;
	}

	static void assertState(Opened opened, List<Statement> expected, boolean complete, String phase)
			throws Exception {
		assertPublicBags(opened, expected, phase);
		TripleStore triples = opened.store().getBackingStore().getTripleStore();
		ValueStore values = (ValueStore) opened.store().getBackingStore().getValueFactory();
		Optional<RdfTermDomain> known = triples.getKnownRdfTermDomain(values.getId(P));
		assertEquals(known, opened.store().getBackingStore().getPersistedRdfTermDomain(P));
		if (known.isPresent()) {
			RdfTermDomain aggregate = expected.stream()
					.map(Statement::getObject)
					.map(RdfTermDomain::classify)
					.reduce(RdfTermDomain::combine)
					.orElseThrow();
			assertEquals(aggregate, known.orElseThrow(),
					"a real old excluded commit cannot leave a false universal integer proof: " + phase);
		}
		if (complete) {
			assertTrue(known.isPresent(), "enabled automatic maintenance must restore complete positive facts");
		}
		triples.trustedTransactionId();
		assertEquals(values.lastTransactionId(), values.trustedClosedTransactionId());
		System.out.println("OLD_ROUNDTRIP_CURRENT_DOMAIN=" + phase + ", known=" + known);
	}

	static void assertPublicBags(Opened opened, List<Statement> expected, String phase) {
		Map<String, Long> statementBag = new TreeMap<>();
		try (var connection = opened.repository().getConnection();
				var statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				statementBag.merge(row(statements.next()), 1L, Long::sum);
			}
		}
		Map<String, Long> expectedBag = new TreeMap<>();
		expected.forEach(statement -> expectedBag.merge(row(statement), 1L, Long::sum));
		assertEquals(expectedBag, statementBag, "whole public statement bag: " + phase);
		EvaluationStrategyFactory original = opened.store().getEvaluationStrategyFactory();
		assertInstanceOf(LmdbEvaluationStrategyFactory.class, original);
		try {
			for (boolean nativeEngine : new boolean[] { false, true }) {
				opened.store()
						.setEvaluationStrategyFactory(nativeEngine
								? new LmdbNativeEvaluationStrategyFactory(opened.store().getFederatedServiceResolver())
								: original);
				assertEquals(nativeEngine, opened.store().isNativeQueryEngineEnabled());
				assertEquals(QueryExecutionPolicy.of(opened.config().isExperimentalQueryOptimizations()),
						opened.store().getQueryExecutionPolicy());
				for (String filter : List.of("", "isIRI(?o)", "isLiteral(?o)", "isNumeric(?o)")) {
					Map<String, Long> actual = new TreeMap<>();
					String sparql = "SELECT ?s ?p ?o ?g WHERE { VALUES ?duplicate { 1 1 } GRAPH ?g { ?s ?p ?o } "
							+ (filter.isEmpty() ? "" : "FILTER(" + filter + ")") + " }";
					try (var connection = opened.repository().getConnection();
							var result = connection.prepareTupleQuery(sparql).evaluate()) {
						while (result.hasNext()) {
							var binding = result.next();
							actual.merge(
									row(VF.createStatement((org.eclipse.rdf4j.model.Resource) binding.getValue("s"),
											(IRI) binding.getValue("p"), binding.getValue("o"),
											(org.eclipse.rdf4j.model.Resource) binding.getValue("g"))),
									1L, Long::sum);
						}
					}
					Map<String, Long> filtered = new TreeMap<>();
					for (Statement statement : expected) {
						Value object = statement.getObject();
						if (filter.isEmpty() || filter.equals("isIRI(?o)") && object instanceof IRI
								|| !filter.equals("isIRI(?o)") && object instanceof org.eclipse.rdf4j.model.Literal) {
							filtered.merge(row(statement), 2L, Long::sum);
						}
					}
					assertEquals(filtered, actual, "whole query bag, native=" + nativeEngine + ": " + phase);
				}
			}
		} finally {
			opened.store().setEvaluationStrategyFactory(original);
		}
		System.out.println("OLD_ROUNDTRIP_PUBLIC_BAGS_PASS=" + phase + ", rows=" + expected.size());
	}

	static Statement initial() {
		return VF.createStatement(VF.createIRI(BASE + "s0"), P, VF.createLiteral("7", XSD.INT), GRAPH);
	}

	static Statement addition() {
		return VF.createStatement(VF.createIRI(BASE + "s1"), P, VF.createIRI(BASE + "object"), GRAPH);
	}

	static String row(Statement statement) {
		return NTriplesUtil.toNTriplesString(statement.getSubject()) + " "
				+ NTriplesUtil.toNTriplesString(statement.getPredicate()) + " "
				+ NTriplesUtil.toNTriplesString(statement.getObject()) + " "
				+ NTriplesUtil.toNTriplesString(statement.getContext());
	}

	static LmdbStoreConfig config(boolean inline, boolean experimental, boolean rebuild) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(inline)
				.setForceSync(true)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexAutoRebuild(rebuild);
		config.setExperimentalQueryOptimizations(experimental);
		return config;
	}

	static Opened open(Path fixture, LmdbStoreConfig config) {
		LmdbStore store = new LmdbStore(fixture.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			return new Opened(store, repository, config);
		} catch (RuntimeException | Error failure) {
			try {
				repository.shutDown();
			} catch (RuntimeException | Error cleanup) {
				if (failure != cleanup) {
					failure.addSuppressed(cleanup);
				}
			}
			throw failure;
		}
	}

	record Opened(LmdbStore store, SailRepository repository, LmdbStoreConfig config) implements AutoCloseable {
		@Override
		public void close() {
			repository.shutDown();
		}
	}
}
